class Apprentice:
    """Represents a blacksmith's apprentice in training."""

    def __init__(self, name, specialty):
        self.name = name
        self.specialty = specialty

    def introduce(self):
        print(f"{self.name} is training in {self.specialty}.")


first_apprentice = Apprentice("Mira", "swordsmithing")
first_apprentice.introduce()

